class_name Player
extends CharacterBody2D

@export var item_spawn_sprite: Sprite2D
@export var interaction_distance: float = 16.0
@export var tilemap_container: Node2D
@export var bobber_scene: PackedScene

var player_direction: Vector2 = Vector2.DOWN
var last_caught_item: ItemData
var active_bobber: Node2D


func get_target_position() -> Vector2:
    var direction := player_direction
    if direction == Vector2.ZERO:
        direction = Vector2.DOWN
    return global_position + direction * interaction_distance


func check_tilemap_at(target_position: Vector2) -> bool:
    if tilemap_container == null:
        return false

    for layer in tilemap_container.get_children():
        if layer is not TileMapLayer:
            continue

        var local_position := layer.to_local(target_position)
        var cell := layer.local_to_map(local_position)
        var tile_data := layer.get_cell_tile_data(cell)

        if tile_data != null:
            if bool(tile_data.get_custom_data("is_water")):
                return true

    return false


func spawn_bobber(position_on_map: Vector2) -> void:
    remove_bobber()

    if bobber_scene == null:
        push_error("Player: bobber_scene is not assigned.")
        return

    active_bobber = bobber_scene.instantiate()
    get_tree().current_scene.add_child(active_bobber)
    active_bobber.global_position = position_on_map


func remove_bobber() -> void:
    if is_instance_valid(active_bobber):
        active_bobber.queue_free()
    active_bobber = null


func show_caught_item(texture: Texture2D) -> void:
    if item_spawn_sprite == null:
        return

    item_spawn_sprite.texture = texture
    item_spawn_sprite.visible = true
    await get_tree().create_timer(2.0).timeout
    item_spawn_sprite.visible = false
    item_spawn_sprite.texture = null

