class_name NodeStateMachine
extends Node

@export var initial_node_state: NodeState

var node_states: Dictionary = {}
var current_node_state: NodeState


func _ready() -> void:
    for child in get_children():
        if child is NodeState:
            var key := child.name.to_lower()
            node_states[key] = child
            child.transition.connect(transition_to)

    if initial_node_state == null:
        push_error("NodeStateMachine: Initial state is not assigned.")
        return

    if not node_states.has(initial_node_state.name.to_lower()):
        push_error("NodeStateMachine: Initial state is not a child.")
        return

    _change_state(initial_node_state)


func _process(delta: float) -> void:
    if is_instance_valid(current_node_state):
        current_node_state._on_process(delta)


func _physics_process(delta: float) -> void:
    if not is_instance_valid(current_node_state):
        return

    current_node_state._on_physics_process(delta)
    current_node_state._on_next_transitions()


func transition_to(state_name: String) -> void:
    var key := state_name.to_lower()

    if not node_states.has(key):
        push_warning("Unknown state: " + state_name)
        return

    var next_state: NodeState = node_states[key]
    if next_state == current_node_state:
        return

    _change_state(next_state)


func _change_state(next_state: NodeState) -> void:
    if is_instance_valid(current_node_state):
        current_node_state._on_exit()

    current_node_state = next_state
    current_node_state._on_enter()

