extends NodeState

@export var player: Player
@export var animated_sprite: AnimatedSprite2D
@export var speed: float = 50.0


func _on_physics_process(_delta: float) -> void:
    var direction := GameInputEvent.movement_input()

    if direction == Vector2.ZERO:
        return

    var facing := direction
    if absf(direction.x) > absf(direction.y):
        facing = Vector2.LEFT if direction.x < 0.0 else Vector2.RIGHT
    else:
        facing = Vector2.UP if direction.y < 0.0 else Vector2.DOWN

    player.player_direction = facing
    player.velocity = direction * speed
    player.move_and_slide()

    if facing == Vector2.UP:
        animated_sprite.play("walk_back")
    elif facing == Vector2.DOWN:
        animated_sprite.play("walk_front")
    elif facing == Vector2.LEFT:
        animated_sprite.play("walk_left")
    else:
        animated_sprite.play("walk_right")


func _on_next_transitions() -> void:
    if not GameInputEvent.is_movement_input():
        transition.emit("Idle")


func _on_exit() -> void:
    animated_sprite.stop()

extends NodeState

@export var player: Player
@export var animated_sprite: AnimatedSprite2D


func _on_enter() -> void:
    player.velocity = Vector2.ZERO

    var target_position := player.get_target_position()
    if not player.check_tilemap_at(target_position):
        transition.emit("Idle")
        return

    if player.player_direction == Vector2.UP:
        animated_sprite.play("fishing_start_back")
    elif player.player_direction == Vector2.LEFT:
        animated_sprite.play("fishing_start_side")
        animated_sprite.flip_h = false
    elif player.player_direction == Vector2.RIGHT:
        animated_sprite.play("fishing_start_side")
        animated_sprite.flip_h = true
    else:
        animated_sprite.play("fishing_start_front")

    await animated_sprite.animation_finished
    player.spawn_bobber(target_position)
    transition.emit("FishingWait")

