class_name GameFishingDatabase

var all_items: Array[ItemData] = []


func _ready() -> void:
    load_all_resources()


func load_all_resources() -> void:
    all_items.clear()

    var directory := DirAccess.open("res://resources/fish/")
    if directory == null:
        push_error("Fish database directory was not found.")
        return

    directory.list_dir_begin()
    var file_name := directory.get_next()

    while file_name != "":
        if not directory.current_is_dir() and file_name.ends_with(".tres"):
            var item_data := load("res://resources/fish/" + file_name) as ItemData
            if item_data != null:
                all_items.append(item_data)
        file_name = directory.get_next()

    directory.list_dir_end()
    print("Loaded fish resources: ", all_items.size())


func get_random_catch(current_period: String) -> ItemData:
    var available: Array[ItemData] = []
    var total_weight := 0.0

    for item_data in all_items:
        if (item_data.allowed_time_periods.is_empty()\n        or current_period in item_data.allowed_time_periods):
            if item_data.drop_weight > 0.0:
                available.append(item_data)
                total_weight += item_data.drop_weight

    if available.is_empty() or total_weight <= 0.0:
        return null

    var roll := randf_range(0.0, total_weight)
    var accumulated := 0.0

    for item_data in available:
        accumulated += item_data.drop_weight
        if roll <= accumulated:
            return item_data

    return available.back()

extends CanvasLayer

signal minigame_finished(success: bool)

@export var water_area: Control
@export var green_bar: ColorRect
@export var fish_icon: TextureRect
@export var progress_bar: TextureProgressBar

var fish_data: ItemData
var green_bar_velocity := 0.0
var fish_target_y := 0.0
var fish_timer := 0.0
var progress := 0.3
var is_active := false

@export var gravity := 800.0
@export var lift_force := 1500.0
@export var max_velocity := 400.0
@export var progress_speed := 0.2
@export var edge_padding := 7.0


func setup(data: ItemData) -> void:
    fish_data = data
    progress = 0.3


func _ready() -> void:
    await get_tree().process_frame
    if fish_data == null:
        push_error("FishingMinigame: fish data was not assigned.")
        queue_free()
        return

    var bar_height := clampf(60.0 - fish_data.difficulty * 4.0, 25.0, 60.0)
    green_bar.size.y = bar_height
    green_bar.position.y = (water_area.size.y - green_bar.size.y) / 2.0
    fish_icon.position.y = water_area.size.y / 2.0

    progress_bar.min_value = 0
    progress_bar.max_value = 100
    progress_bar.value = progress * 100.0

    is_active = true
    _pick_new_fish_target()


func _process(delta: float) -> void:
    if not is_active:
        return

    _update_green_bar(delta)
    _update_fish(delta)
    _update_progress(delta)


func _update_green_bar(delta: float) -> void:
    green_bar_velocity += gravity * delta

    if (Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)\n    or Input.is_action_pressed("ui_accept")):
        green_bar_velocity -= lift_force * delta

    green_bar_velocity = clampf(
        green_bar_velocity,
        -max_velocity,
        max_velocity
    )

    green_bar.position.y += green_bar_velocity * delta

    var max_y := water_area.size.y - green_bar.size.y - edge_padding
    if green_bar.position.y < edge_padding:
        green_bar.position.y = edge_padding
        green_bar_velocity = 0.0
    elif green_bar.position.y > max_y:
        green_bar.position.y = max_y
        green_bar_velocity = 0.0


func _update_fish(delta: float) -> void:
    var speed := fish_data.fish_speed
    fish_icon.position.y = move_toward(
        fish_icon.position.y,
        fish_target_y,
        speed * delta
    )

    fish_timer -= delta
    if fish_timer <= 0.0:
        _pick_new_fish_target()


func _pick_new_fish_target() -> void:
    var max_y := water_area.size.y - fish_icon.size.y - edge_padding
    fish_target_y = randf_range(edge_padding, max_y)
    fish_timer = randf_range(0.5, 1.5)


func _update_progress(delta: float) -> void:
    var fish_center := fish_icon.position.y + fish_icon.size.y / 2.0
    var green_top := green_bar.position.y
    var green_bottom := green_top + green_bar.size.y

    if fish_center >= green_top and fish_center <= green_bottom:
        progress += progress_speed * delta
    else:
        progress -= progress_speed * 1.2 * delta

    progress = clampf(progress, 0.0, 1.0)
    progress_bar.value = progress * 100.0

    if progress >= 1.0:
        _finish(true)
    elif progress <= 0.0:
        _finish(false)


func _finish(success: bool) -> void:
    if not is_active:
        return

    is_active = false
    minigame_finished.emit(success)
    queue_free()

extends NodeState

@export var player: Player
@export var minigame_scene: PackedScene
@export var fish_database: GameFishingDatabase


func _on_enter() -> void:
    var current_period := DayAndNightCycleManager.get_period()
    var caught_item := fish_database.get_random_catch(current_period)

    if caught_item == null:
        player.remove_bobber()
        transition.emit("Idle")
        return

    var minigame := minigame_scene.instantiate()
    player.get_tree().root.add_child(minigame)
    minigame.setup(caught_item)
    minigame.minigame_finished.connect(
        _on_minigame_finished.bind(caught_item),
        CONNECT_ONE_SHOT
    )


func _on_minigame_finished(success: bool, caught_item: ItemData) -> void:
    if success:
        player.last_caught_item = caught_item
        transition.emit("FishingCatch")
    else:
        player.remove_bobber()
        transition.emit("Idle")

